def solve(kind, name):
    class User:
        def __init__(self, name):
            self.name = name

        @classmethod
        def from_row(cls, raw):
            cleaned = raw.strip()
            if not cleaned:
                return "error"
            obj = cls(cleaned)
            return type(obj).__name__.lower() + ":" + obj.name

    class Admin(User):
        pass

    cls = Admin if kind == "admin" else User
    return cls.from_row(name)
